style.css:
body {
  margin: 0;
  width: 350px;
  height: 500px;
  background:
    linear-gradient(#00ffff15 1px, transparent 1px),
    linear-gradient(90deg, #00ffff15 1px, transparent 1px),
    #050505;
  background-size: 40px 40px;
  overflow: hidden;
}

body::before {
  content: "NAORO";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: Consolas, monospace;
  font-size: 4rem;
  letter-spacing: 15px;
  color: #ff00ff;
  text-shadow:
    0 0 10px #ff00ff,
    0 0 30px #ff00ff,
    0 0 60px #ff00ff,
    0 0 100px #ff00ff;
}

body::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      transparent 0 3px,
      rgba(255,255,255,0.03) 4px
    );
  pointer-events: none;
}
